#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long powMod(long long base, long long exp) {
    long long res = 1;
    long long b = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            res = (res * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return res;
}

long long modInverse(long long x) {
    return powMod(x, mod - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;

    long long total = R - L + 1;
    long long E = total / 2 + ((total % 2 == 0 && L % 2 == 0) ? 1 : 0);
    long long O = total - E;

    long long result;
    if ((N * M) % 2 == 1) {
        result = powMod(E + O, N * M);
    } else {
        long long sum = (powMod(E + O, N * M) + powMod(E - O, N * M)) % mod;
        result = (sum * modInverse(2)) % mod;
    }
    cout << result << "\n";
    return 0;
}
